use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl WorkspaceInfoProvider for CargoConfigGeneratorImpl { fn parse_members_file (& self , git_adapter : & dyn GitAdapter , cargo_metadata_provider : & dyn CargoMetadataProvider , project_root : & Path ,) -> Result < Vec < WorkspaceInfo > , anyhow :: Error > { let members_file_path = project_root . join ("submodules/members.txt") ; let members_file_content = std :: fs :: read_to_string (& members_file_path) . context (format ! ("Failed to read members file at {:?}" , members_file_path)) ? ; let mut workspace_infos = Vec :: new () ; for line in members_file_content . lines () { let line = line . trim () ; if line . is_empty () || line . starts_with ('#') { continue ; } let parts : Vec < & str > = line . splitn (2 , ':') . collect () ; if parts . len () != 2 { eprintln ! ("Warning: Malformed line in members.txt: {}" , line) ; continue ; } let submodule_path_str = parts [0] ; let member_crates_str = parts [1] ; let submodule_base_path_rel = PathBuf :: from (submodule_path_str) ; let member_crates : Vec < String > = member_crates_str . split (',') . map (| s | s . trim () . to_string ()) . filter (| s | ! s . is_empty ()) . collect () ; workspace_infos . push (WorkspaceInfo { member_crates , submodule_base_path_rel , }) ; } Ok (workspace_infos) } }